import { spawnSync } from "node:child_process";

const PY_HIDE_WIN = `
import ctypes, sys

class POINT(ctypes.Structure):
    _fields_ = [("x", ctypes.c_long), ("y", ctypes.c_long)]

class CURSORINFO(ctypes.Structure):
    _fields_ = [
        ("cbSize", ctypes.c_uint),
        ("flags", ctypes.c_uint),
        ("hCursor", ctypes.c_void_p),
        ("ptScreenPos", POINT),
    ]

user32 = ctypes.windll.user32
CURSOR_SHOWING = 0x00000001

for _ in range(32):
    info = CURSORINFO()
    info.cbSize = ctypes.sizeof(CURSORINFO)
    if user32.GetCursorInfo(ctypes.byref(info)) and not (info.flags & CURSOR_SHOWING):
        sys.exit(0)
    user32.ShowCursor(False)

sys.exit(0)
`.trim();

const PY_SHOW_WIN = `
import ctypes, sys

class POINT(ctypes.Structure):
    _fields_ = [("x", ctypes.c_long), ("y", ctypes.c_long)]

class CURSORINFO(ctypes.Structure):
    _fields_ = [
        ("cbSize", ctypes.c_uint),
        ("flags", ctypes.c_uint),
        ("hCursor", ctypes.c_void_p),
        ("ptScreenPos", POINT),
    ]

user32 = ctypes.windll.user32
CURSOR_SHOWING = 0x00000001

for _ in range(32):
    info = CURSORINFO()
    info.cbSize = ctypes.sizeof(CURSORINFO)
    if user32.GetCursorInfo(ctypes.byref(info)) and (info.flags & CURSOR_SHOWING):
        sys.exit(0)
    user32.ShowCursor(True)

sys.exit(0)
`.trim();

function getPowerShellCommand(show: boolean) {
	const desiredFlag = show ? 1 : 0;
	const showLiteral = show ? "$true" : "$false";

	return [
		'$signature = @"',
		"using System;",
		"using System.Runtime.InteropServices;",
		"public struct POINT { public int X; public int Y; }",
		"public struct CURSORINFO { public int cbSize; public int flags; public IntPtr hCursor; public POINT ptScreenPos; }",
		"public static class CursorNative {",
		'  [DllImport("user32.dll")] public static extern int ShowCursor(bool show);',
		'  [DllImport("user32.dll")] public static extern bool GetCursorInfo(ref CURSORINFO info);',
		"}",
		'"@;',
		"Add-Type -TypeDefinition $signature -Language CSharp -ErrorAction SilentlyContinue | Out-Null;",
		"$info = New-Object CURSORINFO;",
		"$info.cbSize = [Runtime.InteropServices.Marshal]::SizeOf([type]CURSORINFO);",
		"for ($i = 0; $i -lt 32; $i++) {",
		"  if ([CursorNative]::GetCursorInfo([ref]$info) -and (($info.flags -band 1) -eq " +
			desiredFlag +
			")) { exit 0 }",
		"  [CursorNative]::ShowCursor(" + showLiteral + ") | Out-Null;",
		"}",
		"exit 0",
	].join(" ");
}

function runPythonSnippet(code: string) {
	for (const executable of ["python", "python3", "py"]) {
		const result = spawnSync(executable, ["-c", code], { timeout: 5000 });
		if (!result.error && result.status === 0) {
			return true;
		}
	}

	return false;
}

function runPowerShellSnippet(command: string) {
	const result = spawnSync(
		"powershell.exe",
		["-NoProfile", "-NonInteractive", "-WindowStyle", "Hidden", "-Command", command],
		{ timeout: 8000 },
	);

	return !result.error && result.status === 0;
}

let cursorHidden = false;

export function hideCursor() {
	if (process.platform !== "win32" || cursorHidden) {
		return false;
	}

	try {
		const didHide =
			runPythonSnippet(PY_HIDE_WIN) || runPowerShellSnippet(getPowerShellCommand(false));

		if (didHide) {
			cursorHidden = true;
		}

		return didHide;
	} catch (error) {
		console.error("[cursorHider] Failed to hide Windows cursor:", error);
		return false;
	}
}

export function showCursor() {
	if (process.platform !== "win32" || !cursorHidden) {
		return false;
	}

	try {
		const didShow =
			runPythonSnippet(PY_SHOW_WIN) || runPowerShellSnippet(getPowerShellCommand(true));
		if (didShow) {
			cursorHidden = false;
		}
		return didShow;
	} catch (error) {
		console.error("[cursorHider] Failed to show Windows cursor:", error);
		return false;
	}
}

import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { ensureNativeWindowListBinary } from "../paths/binaries";
import {
	cachedNativeMacWindowSources,
	cachedNativeMacWindowSourcesAtMs,
	interactionCaptureCleanup,
	selectedSource,
	setCachedNativeMacWindowSources,
	setCachedNativeMacWindowSourcesAtMs,
	setInteractionCaptureCleanup,
	setSelectedWindowBounds,
	setWindowBoundsCaptureInterval,
	windowBoundsCaptureInterval,
} from "../state";
import type { NativeMacWindowSource, SelectedSource, WindowBounds } from "../types";
import { parseWindowId } from "../utils";
import { resolveWindowsWindowBounds } from "../windowsWindowControl";

const execFileAsync = promisify(execFile);

export async function getNativeMacWindowSources(options?: { maxAgeMs?: number }) {
	if (process.platform !== "darwin") {
		return [] as NativeMacWindowSource[];
	}

	const maxAgeMs = options?.maxAgeMs ?? 5000;
	const now = Date.now();
	if (cachedNativeMacWindowSources && now - cachedNativeMacWindowSourcesAtMs < maxAgeMs) {
		return cachedNativeMacWindowSources;
	}

	try {
		const binaryPath = await ensureNativeWindowListBinary();
		const { stdout } = await execFileAsync(binaryPath, [], {
			timeout: 30000,
			maxBuffer: 10 * 1024 * 1024,
		});

		const parsed = JSON.parse(stdout);
		if (!Array.isArray(parsed)) {
			return [] as NativeMacWindowSource[];
		}

		const entries = parsed.filter((entry: unknown): entry is NativeMacWindowSource => {
			if (!entry || typeof entry !== "object") {
				return false;
			}

			const candidate = entry as Partial<NativeMacWindowSource>;
			return typeof candidate.id === "string" && typeof candidate.name === "string";
		});

		setCachedNativeMacWindowSources(entries);
		setCachedNativeMacWindowSourcesAtMs(now);
		return entries;
	} catch {
		return cachedNativeMacWindowSources ?? ([] as NativeMacWindowSource[]);
	}
}

export function getWindowBoundsFromNativeSource(
	source?: NativeMacWindowSource | null,
): WindowBounds | null {
	if (!source) {
		return null;
	}

	const { x, y, width, height } = source;
	if (
		typeof x !== "number" ||
		!Number.isFinite(x) ||
		typeof y !== "number" ||
		!Number.isFinite(y) ||
		typeof width !== "number" ||
		!Number.isFinite(width) ||
		typeof height !== "number" ||
		!Number.isFinite(height)
	) {
		return null;
	}

	if (width <= 0 || height <= 0) {
		return null;
	}

	return { x, y, width, height };
}

export async function resolveMacWindowBounds(source: SelectedSource): Promise<WindowBounds | null> {
	const windowId = parseWindowId(source.id);
	if (!windowId) {
		return null;
	}

	try {
		const nativeSources = await getNativeMacWindowSources({ maxAgeMs: 250 });
		const matchedSource = nativeSources.find((entry) => parseWindowId(entry.id) === windowId);
		return getWindowBoundsFromNativeSource(matchedSource);
	} catch {
		return null;
	}
}

export function parseXwininfoBounds(stdout: string): WindowBounds | null {
	const absX = stdout.match(/Absolute upper-left X:\s+(-?\d+)/);
	const absY = stdout.match(/Absolute upper-left Y:\s+(-?\d+)/);
	const width = stdout.match(/Width:\s+(\d+)/);
	const height = stdout.match(/Height:\s+(\d+)/);

	if (!absX || !absY || !width || !height) {
		return null;
	}

	return {
		x: Number.parseInt(absX[1], 10),
		y: Number.parseInt(absY[1], 10),
		width: Number.parseInt(width[1], 10),
		height: Number.parseInt(height[1], 10),
	};
}

export async function resolveLinuxWindowBounds(
	source: SelectedSource,
): Promise<WindowBounds | null> {
	const windowId = parseWindowId(source?.id);

	if (windowId) {
		try {
			const { stdout } = await execFileAsync("xwininfo", ["-id", String(windowId)], {
				timeout: 1500,
			});
			const bounds = parseXwininfoBounds(stdout);
			if (bounds && bounds.width > 0 && bounds.height > 0) {
				return bounds;
			}
		} catch {
			// fall back to title lookup below
		}
	}

	const windowTitle =
		typeof source.windowTitle === "string" ? source.windowTitle.trim() : source.name.trim();
	if (!windowTitle) {
		return null;
	}

	try {
		const { stdout } = await execFileAsync("xwininfo", ["-name", windowTitle], {
			timeout: 1500,
		});
		const bounds = parseXwininfoBounds(stdout);
		return bounds && bounds.width > 0 && bounds.height > 0 ? bounds : null;
	} catch {
		return null;
	}
}

export function stopInteractionCapture() {
	if (interactionCaptureCleanup) {
		interactionCaptureCleanup();
		setInteractionCaptureCleanup(null);
	}
}

export function stopWindowBoundsCapture() {
	if (windowBoundsCaptureInterval) {
		clearInterval(windowBoundsCaptureInterval);
		setWindowBoundsCaptureInterval(null);
	}
	setSelectedWindowBounds(null);
}

async function refreshSelectedWindowBounds() {
	if (!selectedSource?.id?.startsWith("window:")) {
		setSelectedWindowBounds(null);
		return;
	}

	let bounds: WindowBounds | null = null;

	if (process.platform === "darwin") {
		bounds = await resolveMacWindowBounds(selectedSource);
	} else if (process.platform === "win32") {
		bounds = await resolveWindowsWindowBounds(selectedSource);
	} else if (process.platform === "linux") {
		bounds = await resolveLinuxWindowBounds(selectedSource);
	}

	setSelectedWindowBounds(bounds);
}

export function startWindowBoundsCapture() {
	stopWindowBoundsCapture();

	if (
		!["darwin", "win32", "linux"].includes(process.platform) ||
		!selectedSource?.id?.startsWith("window:")
	) {
		return;
	}

	void refreshSelectedWindowBounds();
	setWindowBoundsCaptureInterval(
		setInterval(() => {
			void refreshSelectedWindowBounds();
		}, 250),
	);
}

'use client'

import { Icon } from '@iconify/react'
import { memo, useLayoutEffect, useMemo, useRef, useState } from 'react'
import useEditor, { type FloorplanSelectionTool } from '../../store/use-editor'
import { useFloorplanDraftPreview } from '../../store/use-floorplan-draft-preview'
import { furnishTools } from '../ui/action-menu/furnish-tools'
import { tools as structureTools } from '../ui/action-menu/structure-tools'
import {
  type FloorplanCursorPoint,
  projectFloorplanCursorPoint,
  resolveFloorplanCursorIndicatorPosition,
} from './floorplan-cursor-indicator-position'

type FloorplanCursorIndicator =
  | {
      kind: 'asset'
      iconSrc: string
    }
  | {
      kind: 'icon'
      icon: string
    }

type FloorplanCursorIndicatorOverlayProps = {
  cursorPosition: FloorplanCursorPoint | null
  floorplanSelectionTool: FloorplanSelectionTool
  movingOpeningType: 'door' | 'window' | null
  isPanning: boolean
  cursorColor: string
  indicatorLineHeight?: number
  indicatorBadgeOffsetX?: number
  indicatorBadgeOffsetY?: number
}

export const FloorplanCursorIndicatorOverlay = memo(function FloorplanCursorIndicatorOverlay({
  cursorPosition,
  floorplanSelectionTool,
  movingOpeningType,
  isPanning,
  cursorColor,
  indicatorLineHeight = 18,
  indicatorBadgeOffsetX = 14,
  indicatorBadgeOffsetY = 14,
}: FloorplanCursorIndicatorOverlayProps) {
  const mode = useEditor((state) => state.mode)
  const tool = useEditor((state) => state.tool)
  const structureLayer = useEditor((state) => state.structureLayer)
  const catalogCategory = useEditor((state) => state.catalogCategory)
  const cursorPoint = useFloorplanDraftPreview((state) => state.cursorPoint)
  const anchorRef = useRef<HTMLDivElement>(null)
  const [projectedCursorPosition, setProjectedCursorPosition] =
    useState<FloorplanCursorPoint | null>(null)

  const activeFloorplanToolConfig = useMemo(() => {
    if (movingOpeningType) {
      return structureTools.find((entry) => entry.id === movingOpeningType) ?? null
    }

    if (mode !== 'build' || !tool) {
      return null
    }

    if (tool === 'item' && catalogCategory) {
      return furnishTools.find((entry) => entry.catalogCategory === catalogCategory) ?? null
    }

    return structureTools.find((entry) => entry.id === tool) ?? null
  }, [catalogCategory, mode, movingOpeningType, tool])

  const indicator = useMemo<FloorplanCursorIndicator | null>(() => {
    if (activeFloorplanToolConfig) {
      return { kind: 'asset', iconSrc: activeFloorplanToolConfig.iconSrc }
    }

    if (mode === 'select' && floorplanSelectionTool === 'marquee' && structureLayer !== 'zones') {
      return { kind: 'icon', icon: 'mdi:select-drag' }
    }

    if (mode === 'delete') {
      return { kind: 'icon', icon: 'mdi:trash-can-outline' }
    }

    if (mode === 'material-paint') {
      return { kind: 'asset', iconSrc: '/icons/paint.webp' }
    }

    return null
  }, [activeFloorplanToolConfig, floorplanSelectionTool, mode, structureLayer])

  useLayoutEffect(() => {
    const anchor = anchorRef.current
    const overlayHost = anchor?.parentElement
    const scene = overlayHost?.querySelector<SVGGElement>('[data-floorplan-scene]')
    const sceneToViewport = scene?.getScreenCTM()

    if (!(cursorPoint && cursorPosition && overlayHost && sceneToViewport)) {
      setProjectedCursorPosition(null)
      return
    }

    const overlayRect = overlayHost.getBoundingClientRect()
    const nextPosition = projectFloorplanCursorPoint(cursorPoint, sceneToViewport, {
      x: overlayRect.left,
      y: overlayRect.top,
    })
    setProjectedCursorPosition((currentPosition) =>
      currentPosition &&
      currentPosition.x === nextPosition.x &&
      currentPosition.y === nextPosition.y
        ? currentPosition
        : nextPosition,
    )
  }, [cursorPoint, cursorPosition])

  const position = resolveFloorplanCursorIndicatorPosition(cursorPosition, projectedCursorPosition)

  if (!(indicator && position) || isPanning) {
    return null
  }

  return (
    <div
      aria-hidden="true"
      className="pointer-events-none absolute z-20"
      ref={anchorRef}
      style={{ left: position.x, top: position.y }}
    >
      {mode === 'delete' ? (
        <div
          className="flex h-8 w-8 items-center justify-center rounded-xl border border-white/5 bg-zinc-900/95 shadow-[0_8px_16px_-4px_rgba(0,0,0,0.3),0_4px_8px_-4px_rgba(0,0,0,0.2)]"
          style={{
            boxShadow: `0 8px 16px -4px rgba(0,0,0,0.3), 0 4px 8px -4px rgba(0,0,0,0.2), 0 0 18px ${cursorColor}22`,
            transform: `translate(${indicatorBadgeOffsetX}px, ${indicatorBadgeOffsetY}px)`,
          }}
        >
          {indicator.kind === 'asset' ? (
            <img
              alt=""
              aria-hidden="true"
              className="h-5 w-5 object-contain drop-shadow-[0_2px_4px_rgba(0,0,0,0.5)]"
              src={indicator.iconSrc}
            />
          ) : (
            <Icon
              aria-hidden="true"
              className="drop-shadow-[0_2px_4px_rgba(0,0,0,0.5)]"
              color={cursorColor}
              height={18}
              icon={indicator.icon}
              width={18}
            />
          )}
        </div>
      ) : (
        <>
          <div
            className="absolute top-0 left-1/2 w-px -translate-x-1/2 -translate-y-full"
            style={{
              backgroundColor: cursorColor,
              boxShadow: `0 0 12px ${cursorColor}55`,
              height: indicatorLineHeight,
            }}
          />
          <div
            className="absolute top-0 left-1/2 flex h-8 w-8 items-center justify-center rounded-xl border border-white/5 bg-zinc-900/95 shadow-[0_8px_16px_-4px_rgba(0,0,0,0.3),0_4px_8px_-4px_rgba(0,0,0,0.2)]"
            style={{
              transform: `translate(-50%, calc(-100% - ${indicatorLineHeight}px))`,
            }}
          >
            {indicator.kind === 'asset' ? (
              <img
                alt=""
                aria-hidden="true"
                className="h-5 w-5 object-contain drop-shadow-[0_2px_4px_rgba(0,0,0,0.5)]"
                src={indicator.iconSrc}
              />
            ) : (
              <Icon
                aria-hidden="true"
                className="drop-shadow-[0_2px_4px_rgba(0,0,0,0.5)]"
                color="white"
                height={18}
                icon={indicator.icon}
                width={18}
              />
            )}
          </div>
        </>
      )}
    </div>
  )
})

'use client'

import type { ZoneNode as ZoneNodeType } from '@pascal-app/core'
import type { WallPlanPoint } from '../tools/wall/wall-drafting'

type ModifierKeys = {
  meta: boolean
  ctrl: boolean
  shift: boolean
  /** Alt alone: select one session-group member without expanding. */
  alt: boolean
}

type ResolveFloorplanBackgroundSelectionArgs = {
  canSelectElementFloorplanGeometry: boolean
  canSelectFloorplanZones: boolean
  currentSelectedIds: string[]
  /** Session-group expand on plain click (not on modifier/Alt). */
  expandIdsForNode?: (nodeId: string) => string[] | null
  getFloorplanHitIdAtPoint: (planPoint: WallPlanPoint) => string | null
  isWallBuildActive: boolean
  modifierKeys: ModifierKeys
  planPoint: WallPlanPoint
  structureLayer: string
}

function hasToggleModifier(modifierKeys: ModifierKeys): boolean {
  return modifierKeys.meta || modifierKeys.ctrl || modifierKeys.shift
}

function resolveHitSelection(
  hitId: string,
  currentSelectedIds: string[],
  modifierKeys: ModifierKeys,
  expandIdsForNode?: (nodeId: string) => string[] | null,
): string[] {
  if (hasToggleModifier(modifierKeys)) {
    return currentSelectedIds.includes(hitId)
      ? currentSelectedIds.filter((selectedId) => selectedId !== hitId)
      : [...currentSelectedIds, hitId]
  }
  if (modifierKeys.alt) return [hitId]
  const expanded = expandIdsForNode?.(hitId)
  return expanded && expanded.length > 1 ? expanded : [hitId]
}

export type FloorplanBackgroundSelectionResult =
  | {
      handled: true
      kind: 'select-zone'
      zoneId: ZoneNodeType['id']
    }
  | {
      handled: true
      kind: 'select-elements'
      selectedIds: string[]
    }
  | {
      handled: true
      kind: 'clear-zones'
    }
  | {
      handled: true
      kind: 'clear-elements'
      preserveSelection: boolean
    }
  | {
      handled: false
    }

export function resolveFloorplanBackgroundSelection({
  canSelectElementFloorplanGeometry,
  canSelectFloorplanZones,
  currentSelectedIds,
  expandIdsForNode,
  getFloorplanHitIdAtPoint,
  isWallBuildActive,
  modifierKeys,
  planPoint,
  structureLayer,
}: ResolveFloorplanBackgroundSelectionArgs): FloorplanBackgroundSelectionResult {
  if (canSelectFloorplanZones) {
    const zoneId = getFloorplanHitIdAtPoint(planPoint)
    if (zoneId) {
      return {
        handled: true,
        kind: 'select-zone',
        zoneId: zoneId as ZoneNodeType['id'],
      }
    }
  }

  if (canSelectElementFloorplanGeometry) {
    const hitId = getFloorplanHitIdAtPoint(planPoint)
    if (hitId) {
      return {
        handled: true,
        kind: 'select-elements',
        selectedIds: resolveHitSelection(hitId, currentSelectedIds, modifierKeys, expandIdsForNode),
      }
    }
  }

  if (!isWallBuildActive) {
    if (structureLayer === 'zones') {
      return {
        handled: true,
        kind: 'clear-zones',
      }
    }

    return {
      handled: true,
      kind: 'clear-elements',
      preserveSelection: hasToggleModifier(modifierKeys),
    }
  }

  return { handled: false }
}

